schemas.schema-01-systematic.prisma:
/// Platform sales channel configuration - This implements the cross-channel and modular marketplace requirement from 'Architecture & Extensibility (07_ai-mall_architecture-and-extensibility.md)'. Provides foundational separation for mall operations by defining unique sales channels (web, app, third-party). Maintains 3NF structure by keeping channel-specific configuration here, without duplicating in lower-level business tables. Example: creation of a 'BrandA Global Web Store' or 'Mobile App Korea'. Key relationships: Referenced by sections, categories, file usages. Special behaviors: Channel can be disabled without deletion for staged launches or regulatory holds.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique identifier for the sales channel. Implements channel abstraction reference. Allows for lookup and management by business and system APIs. Example: 'KR_WEB', 'US_MOBILE'. Must be unique.
  code String

  /// Human-readable channel label. Example: 'Korea Web Store', 'Global Mobile App'.
  name String

  /// Brand association for multi-brand platforms. Example: 'BrandA', 'GenericMall'.
  brand String?

  /// Whether this channel is currently active/published to users.
  enabled Boolean

  /// Timestamp when the channel was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last channel update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_sections ai_mall_sections[]
  ai_mall_orders ai_mall_orders[]

  @@unique([code])
  @@index([enabled])
}

/// Channel sections configuration - Implements extensible, configurable sections for each sales channel, as described in 'Architecture & Extensibility'. Business purpose: Allows flexible segmentation within a channel (e.g., Electronics, Lifestyle, Flash Sale). Maintains 3NF by holding only section-level config/reference—products/content are managed separately. Example: a channel may have 'Home', 'Deals', or 'Electronics' sections. Key relationships: Links to {@link ai_mall_channels.id}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent channel's {@link ai_mall_channels.id}. Each section is tied to a channel, enforcing modular configuration. Required foreign key association.
  ai_mall_channel_id String @db.Uuid

  /// Unique identifier for section within the channel.
  code String

  /// User-facing section name (e.g., 'Flash Sale', 'Kids').
  name String

  /// Sort order of sections within a channel.
  order Int? @db.Integer

  /// Is this section active and visible on the channel?
  enabled Boolean

  /// Timestamp section was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last section update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_sections_channel ai_mall_channels @relation(fields: [ai_mall_channel_id], references: [id], onDelete: Cascade)

  @@unique([ai_mall_channel_id, code])
  @@index([ai_mall_channel_id])
}

/// Flexible multi-level taxonomy for mall navigation - Implements hierarchical category management from 'Product & Content Management'. Enables unlimited nesting/category grouping for products and content. Maintains strict normalization by keeping category structure atomic and storing only hierarchy metadata here (not product links). Example: creation of 'Electronics > Phones > Smartphones', reordering, reparenting. Key relationships: Optional parent-child self-reference allows tree structure.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent category's {@link ai_mall_categories.id}. Enables recursive taxonomy. Nullable root-level. Maintains hierarchical structure in 3NF.
  parent_id String? @db.Uuid

  /// Unique business identifier for the category. Example: 'ELEC_SMARTPHONES', 'TOYS_OUTDOOR'.
  code String

  /// Display name for category (multi-lingual UI supported at app layer).
  name String

  /// Category nesting depth (e.g., 0=root, 1=child, 2=grandchild).
  level Int @db.Integer

  /// Sort order within siblings.
  order Int? @db.Integer

  /// Is the category active and visible for filtering/browsing?
  enabled Boolean

  /// Timestamp category was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_categories_parent ai_mall_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_mall_categories[] @relation("recursive")
  ai_mall_category_products ai_mall_category_products[]

  @@unique([code])
  @@index([parent_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Attachment and file repository for mall resources - Implements file/media management as in 'Architecture (07_ai-mall_architecture-and-extensibility.md)'. Manages all uploaded files (images, videos, docs), storing metadata but not raw content. Example: product images, manuals, admin banners. Used by products, promotions, articles, etc. Business logic for file lifecycle (expiry, visibility) starts here.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_files {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Permanent location of the file in cloud, CDN, or on-prem storage.
  uri String @db.VarChar(80000)

  /// Original file name with extension.
  name String

  /// Media type (MIME), e.g., 'image/png'.
  type String

  /// File size in bytes.
  size Int @db.Integer

  /// Upload timestamp for audit and security reviews.
  created_at DateTime @db.Timestamptz

  /// Optional expiration/deletion timestamp.
  expires_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_file_usages ai_mall_file_usages[]
  ai_mall_product_images ai_mall_product_images[]

  @@index([type])
  @@index([expires_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Mapping of files to business resources (products, channels, etc.) - Implements domain-agnostic usage log as described in 'Architecture'. Enables the same file to be attached to many business entities across domains, while separate from core file repository. Maintains 3NF: no reference info is stored in ai_mall_files; all usage links and field-specific meta go here. Example: link file id X to 'cover_image' of product Y. Special behaviors: file usage field enables typed attachments.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_file_usages {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced file's {@link ai_mall_files.id}. Required foreign key association.
  ai_mall_file_id String @db.Uuid

  /// Domain of usage, e.g., 'product', 'promotion', 'article'.
  usage_domain String

  /// Specific field context (e.g., 'cover_image').
  usage_field String

  /// UUID of the linked business entity (product, channel, section, etc.).
  entity_id String @db.Uuid

  /// Timestamp usage link was established.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_file_usages_file ai_mall_files @relation(fields: [ai_mall_file_id], references: [id], onDelete: Cascade)

  @@unique([ai_mall_file_id, usage_domain, usage_field, entity_id])
  @@index([usage_domain])
  @@index([entity_id])
}

/// API Gateway registry/coordination - Implements security, endpoint, and routing control as described in 'Architecture'. Records metadata for each API gateway (core, internal, partner, test environments). Maintains 3NF: endpoint/routing data only, logs/stats are segregated elsewhere. Example: 'Public Core Gateway', 'Partner Channel Gateway'. Special behaviors: Gateways can be enabled/disabled for maintenance.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_api_gateways {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique gateway code. Example: 'CORE', 'PARTNER', 'TESTNET'.
  code String

  /// Display name/label for management UI.
  name String

  /// Base endpoint URL (e.g., 'https://api.mall.com/core').
  base_url String @db.VarChar(80000)

  /// Whether this gateway is currently handling traffic.
  enabled Boolean

  /// Timestamp when gateway was added.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last gateway update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([enabled])
}

/// System-wide audit trail for compliance and troubleshooting - Implements audit log requirements from 'Security, Compliance & Accessibility'. Captures every critical action (user, admin, system) in a unified, immutable ledger for security and compliance. Maintains 3NF; audit log is append-only, no business data is duplicated. Example: admin disables a channel, user edits their role. Links actions to actor/entity via actor_id, entity_domain, and entity_id. All cross-table references are soft for extensibility.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Canonical name of action performed (e.g., 'channel_disable').
  action String

  /// Role performing the action (e.g., 'admin', 'seller', 'system').
  actor_role String?

  /// UUID of user/system performing the action.
  actor_id String? @db.Uuid

  /// Entity domain this log references (e.g., 'channel').
  entity_domain String?

  /// UUID of the entity record acted upon.
  entity_id String? @db.Uuid

  /// IP address linked to the action.
  ip String?

  /// Structured or free-form log payload with action metadata/data.
  details String?

  /// Timestamp when the action/log was recorded.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([entity_domain, entity_id])
  @@index([actor_role])
  @@index([created_at])
}

/// Global and module-specific configuration registry - Implements platform-wide and modular configuration patterns from 'Architecture'. Stores key-value config for all mall subsystems (feature flags, UI settings, 3rd-party integration keys). Every setting is a separate row with unique key, value, and optional group/domain. Example: toggling AI segments, maintenance windows. Fully normalized.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Canonical config key (e.g., 'feature/recommendations.enabled').
  key String

  /// Current value for the key (string-encoded for flexibility).
  value String

  /// Configuration domain/group (e.g., 'feature').
  group String?

  /// Optional description for admin UI, change log, or documentation.
  description String?

  /// Timestamp when the key was created.
  created_at DateTime @db.Timestamptz

  /// Last modified time for this key/value.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([group])
}

schemas.schema-02-actors.prisma:
/// Customer accounts - This implements the platform's customer account system from the user role and management requirements. Business users marked as customers for ownership of carts, orders, reviews, and personalization. Maintains 3NF by using normalized foreign keys to auth/user states. For example, a customer making a purchase will be linked here. Key relationships: references user profile, authentication, active state. Special behaviors: only non-admin, non-seller users belong here; customers can transition to seller.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged profile's {@link ai_mall_user_profiles.id}. Profile association for customer details and preference data. Required for linking demographic and personalization info.
  user_profile_id String @db.Uuid

  /// Authentication details {@link ai_mall_authentications.id}. Secures login credentials. Required for SSO, OAuth, multi-factor.
  authentication_id String @db.Uuid

  /// Current state {@link ai_mall_user_states.id}. Shows if active, suspended, pending. Used for soft deletion and compliance audit.
  user_state_id String @db.Uuid

  /// Timestamp of account creation. Implements onboarding flow compliance.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update. Auditing user changes.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profile ai_mall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)
  authentication ai_mall_authentications @relation(fields: [authentication_id], references: [id], onDelete: Cascade)
  user_state ai_mall_user_states @relation(fields: [user_state_id], references: [id], onDelete: Cascade)

  ai_mall_carts ai_mall_carts[]
  ai_mall_orders ai_mall_orders[]
  ai_mall_coupon_issuances ai_mall_coupon_issuances[]
  ai_mall_loyalty_point_ledgers ai_mall_loyalty_point_ledgers[]
  ai_mall_deposits ai_mall_deposits[]
  ai_mall_point_transactions ai_mall_point_transactions[]
  ai_mall_point_balances ai_mall_point_balances?
  ai_mall_inquiries ai_mall_inquiries[]
  ai_mall_inquiry_comments ai_mall_inquiry_comments[]
  ai_mall_reviews ai_mall_reviews[]
  ai_mall_review_comments ai_mall_review_comments[]
  ai_mall_feedbacks ai_mall_feedbacks[]
  ai_mall_favorites ai_mall_favorites[]
  ai_mall_wishlists ai_mall_wishlists[]
  ai_mall_collections ai_mall_collections[]
  ai_mall_article_comments ai_mall_article_comments[]

  @@unique([user_profile_id])
  @@unique([authentication_id])
  @@index([user_state_id])
}

/// Seller accounts - Implements the merchant/seller role from requirements. Seller ownership over storefronts, product listings, and order fulfillment. Maintains 3NF; separated from customer/admin for permissioning. For example, a merchant dashboard references this. Key relationships: links to user profile and authentication. Special behaviors: future role upgrade/downgrade mapping.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged profile's {@link ai_mall_user_profiles.id}. Tied to individual or business profile for seller.
  user_profile_id String @db.Uuid

  /// Authentication source {@link ai_mall_authentications.id}. Seller login.
  authentication_id String @db.Uuid

  /// Account status {@link ai_mall_user_states.id}. Active/verified/suspended checks.
  user_state_id String @db.Uuid

  /// Seller account creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Seller record last update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profile ai_mall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)
  authentication ai_mall_authentications @relation(fields: [authentication_id], references: [id], onDelete: Cascade)
  user_state ai_mall_user_states @relation(fields: [user_state_id], references: [id], onDelete: Cascade)

  ai_mall_products ai_mall_products[]
  ai_mall_orders ai_mall_orders[]
  ai_mall_inquiry_comments ai_mall_inquiry_comments[]
  ai_mall_review_comments ai_mall_review_comments[]
  ai_mall_feedbacks ai_mall_feedbacks[]
  ai_mall_articles ai_mall_articles[]
  ai_mall_article_comments ai_mall_article_comments[]

  @@unique([user_profile_id])
  @@unique([authentication_id])
  @@index([user_state_id])
}

/// Admin operator accounts - Implements the admin role from user roles requirements. Used for full access, compliance monitoring, and global configuration. Maintains full normalization and strict isolation from customer/seller models. Example usage: admin dashboards and audit logs reference this entity. Key relationships: profile, authentication, state. Special behavior: audit logging and permission elevation/revocation.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin profile reference {@link ai_mall_user_profiles.id}. Admin identity; critical for operations.
  user_profile_id String @db.Uuid

  /// Authentication details {@link ai_mall_authentications.id}. Responsible for login traceability and MFA.
  authentication_id String @db.Uuid

  /// Current admin state {@link ai_mall_user_states.id}. For privilege control & suspension.
  user_state_id String @db.Uuid

  /// Admin record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last admin record update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profile ai_mall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)
  authentication ai_mall_authentications @relation(fields: [authentication_id], references: [id], onDelete: Cascade)
  user_state ai_mall_user_states @relation(fields: [user_state_id], references: [id], onDelete: Cascade)

  ai_mall_order_snapshots ai_mall_order_snapshots[]
  ai_mall_order_payments ai_mall_order_payments[]
  ai_mall_order_fulfillments ai_mall_order_fulfillments[]
  ai_mall_order_fraud_flags ai_mall_order_fraud_flags[]
  ai_mall_inquiry_comments ai_mall_inquiry_comments[]
  ai_mall_review_comments ai_mall_review_comments[]
  ai_mall_feedbacks ai_mall_feedbacks[]
  ai_mall_articles ai_mall_articles[]
  ai_mall_article_comments ai_mall_article_comments[]

  @@unique([user_profile_id])
  @@unique([authentication_id])
  @@index([user_state_id])
}

/// User profile master record - Implements unified identity and profile normalization from requirements. Profiles can be reused/linked across roles (customer/seller/admin). Maintains 3NF and prevents duplicate user records per person/email. For example, profile settings update or role transition occurs here. Key relationships: links to all role tables, not just one. Special behaviors: versioned changes, personal detail enrichment.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_user_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Primary email address. Implements contact identity. Uniqueness across users. Used for login, notification, and compliance.
  email String

  /// Optional phone for user. Used in authentication and notification flows.
  phone_number String?

  /// Full name per user profile. Used in personalization and communications.
  full_name String

  /// User's chosen nickname. Shown publicly in reviews, inquiries, etc.
  nickname String?

  /// Avatar/profile photo URL for UI. Maintains normalization. Used in user settings screen, not business logic.
  avatar_url String? @db.VarChar(80000)

  /// Profile creation timestamp. Audit/compliance.
  created_at DateTime @db.Timestamptz

  /// Profile updated timestamp. Tracing edits/auditing.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_customers ai_mall_customers?
  ai_mall_sellers ai_mall_sellers?
  ai_mall_admins ai_mall_admins?
  ai_mall_authentications ai_mall_authentications?
  ai_mall_role_assignments ai_mall_role_assignments[]

  @@unique([email])
  @@index([nickname])
  @@index([full_name])
  @@index([nickname(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([full_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// User authentication credentials and methods - Implements credential and authentication records from requirement. Aggregates authentication factors (password hash, SSO/OAuth, MFA tokens) while linking to profiles. Maintains normalization, supports flexible auth provider integration. For example, signing in checks this entity. Key relationships: referenced by customer/seller/admin; ties to user profile. Special behaviors: securely stores only hashes/tokens, never plaintext secrets.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_authentications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked profile's {@link ai_mall_user_profiles.id}. Supports auditing/attribution of auth events.
  user_profile_id String @db.Uuid

  /// Type of authentication (e.g., 'password','oauth','sso','sms'). Fulfills identity management flexibility.
  auth_type String

  /// Principal ID (username, email, OAuth sub). Implements login state. Calculated at login. Needs to be unique for provider/user.
  identifier String

  /// Credential hash/token (never raw passwords). Ensures security compliance. Used for login validation only.
  credential_hash String

  /// Is Multi-Factor Auth enabled. Implements compliance, audit, and security hardening. Used for step-up auth flows.
  mfa_enabled Boolean

  /// Credential record created at.
  created_at DateTime @db.Timestamptz

  /// Credential record last updated at.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profile ai_mall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_mall_customers ai_mall_customers?
  ai_mall_sellers ai_mall_sellers?
  ai_mall_admins ai_mall_admins?

  @@unique([user_profile_id])
  @@unique([identifier])
  @@index([auth_type])
  @@index([identifier(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Role master - Implements business rule management for user roles (customer, seller, admin, and future custom roles). 3NF normalization, supports extensible platform role-based permissions. For example, role assignment/upgrade occurs here. Key relationships: role_assignments, used by core tables. Special behaviors: reserved roles enforced for compliance (cannot delete base roles).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_roles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique role code (e.g., 'customer', 'seller', 'admin'). Implements enum-like role logic throughout platform. Used for user gating, permission checks.
  code String

  /// Translatable display name. E.g., 'Customer', 'Seller', 'Admin'. Used in UIs.
  name String

  /// Long-form explanation/description of the role. For admin UIs and auditing. E.g., rationale for this role's permissions.
  description String?

  /// Role record created at.
  created_at DateTime @db.Timestamptz

  /// Role record last updated at.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_role_assignments ai_mall_role_assignments[]

  @@unique([code])
  @@unique([name])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// User-role assignment mapping - Implements user-to-role assignment per requirements for flexible permissioning and transitions. Supports audit tracking of who/why/when a user received or lost a role. Maintains 3NF (separate entity for reassignments and audit trail). For example, transitioning a customer to a seller creates a new assignment. Key relationships: user (profile), role; each user can have multiple role assignments over time. Special behaviors: tracks assignment/detachment reason/timing for audit and rollback.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_role_assignments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User being assigned {@link ai_mall_user_profiles.id}. User for the assignment. Allows one-to-many mapping (user can have multiple roles over time).
  user_profile_id String @db.Uuid

  /// Assigned role {@link ai_mall_roles.id}. Links assignment to the role entity.
  role_id String @db.Uuid

  /// Timestamp of role assignment creation.
  assigned_at DateTime @db.Timestamptz

  /// Timestamp of role detachment/deactivation (null if still active). Implements access revocation.
  detached_at DateTime? @db.Timestamptz

  /// Human-readable description of the assignment/detachment reason (optional). Used for audit logging.
  reason String?

  //----
  // RELATIONS
  //----
  user_profile ai_mall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)
  role ai_mall_roles @relation(fields: [role_id], references: [id], onDelete: Cascade)

  @@index([role_id])

  @@index([user_profile_id, role_id])
}

/// User state system - Implements state management for active, suspended, pending verification, or deleted users. Centralizes state for all roles to ensure consistent permission and compliance handling. Maintains 3NF; no duplication of state indicator in user records. For example: when customer is suspended, this state is referenced. Key relationships: referenced by all actor tables. Special behaviors: state transitions are logged, only valid states exist here.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_user_states {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique code identifying the state (e.g., 'active', 'suspended', 'pending', 'deleted'). Used for fast gating and compliance audits.
  code String

  /// Translatable state name ('Active','Suspended','Pending','Deleted'). For admin UIs and user logs.
  name String

  /// Human/long-form description of state. For audit/compliance and admin reference. E.g., when/how state is assigned.
  description String?

  /// Record state creation timestamp.
  created_at DateTime @db.Timestamptz

  /// State record last updated at.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_customers ai_mall_customers[]
  ai_mall_sellers ai_mall_sellers[]
  ai_mall_admins ai_mall_admins[]

  @@unique([code])
  @@unique([name])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-products.prisma:
/// Product master data table - Implements product entity required for catalog, as per requirements analysis (Section 3). 3NF-compliant. Example: Seller creates a product, links variants, images, tags, categories. Key: brand, seller, category, snapshot versioning. Special: Product lifecycle, audit log. Unique: sku, slug.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated brand's {@link ai_mall_brands.id}. Identifies product brand for filtering, analytics, offers.
  ai_mall_brand_id String? @db.Uuid

  /// Product seller's {@link ai_mall_sellers.id}. Links to seller (owner) of the product. Maintains seller's catalog ownership.
  ai_mall_seller_id String @db.Uuid

  /// Stock keeping unit, implements unique product tracking. Example: 'PROD12345'.
  sku String

  /// Product display name. Example: 'Wireless Earbuds'.
  name String

  /// Short product summary, for quick reference.
  description String?

  /// Product state (draft, under_review, published, archived). Example: 'published'.
  status String

  /// Primary image URL. Only main image is here; all other images are in ai_mall_product_images for normalization.
  main_image_url String? @db.VarChar(80000)

  /// SEO meta title. For search optimization.
  meta_title String?

  /// SEO meta description.
  meta_description String?

  /// Unique SEO slug for product page URL. Example: 'wireless-earbuds-2025'.
  slug String

  /// Creation timestamp. For audit/data lineage traceability.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion marker. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  BrandProduct ai_mall_brands? @relation(fields: [ai_mall_brand_id], references: [id], onDelete: Cascade)
  SellerProduct ai_mall_sellers @relation(fields: [ai_mall_seller_id], references: [id], onDelete: Cascade)

  ai_mall_product_variants ai_mall_product_variants[]
  ai_mall_product_images ai_mall_product_images[]
  ai_mall_product_tags ai_mall_product_tags[]
  ai_mall_product_attributes ai_mall_product_attributes[]
  ai_mall_category_products ai_mall_category_products[]
  ai_mall_product_snapshots ai_mall_product_snapshots[]
  ai_mall_cart_items ai_mall_cart_items[]
  ai_mall_inquiries ai_mall_inquiries[]
  ai_mall_reviews ai_mall_reviews[]
  ai_mall_favorites ai_mall_favorites[]
  ai_mall_wishlist_items ai_mall_wishlist_items[]
  ai_mall_collection_items ai_mall_collection_items[]

  @@index([ai_mall_brand_id])

  @@unique([sku])
  @@unique([slug])
  @@index([ai_mall_seller_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([meta_title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product variant detail table - Implements variant logic (multi-dimensional SKUs, Section 5). Stores atomic option values (e.g., color, size), price, stock per variant. Maintains 3NF. Example: 'Red/Small', 'Blue/Large'. Relationships: main product and inventory. Uniqueness: per product, audit trail via timestamps.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged product's {@link ai_mall_products.id}.
  ai_mall_product_id String @db.Uuid

  /// Unique SKU per variant. Example: 'PROD123-A1'.
  sku String

  /// Variant option encoding (e.g., 'color:red;size:m').
  option_key String

  /// Sale price per variant. Example: 49.99.
  price Float @db.DoublePrecision

  /// Variant inventory. Example: 100.
