model ai_mall_category_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked product's {@link ai_mall_products.id}.
  ai_mall_product_id String @db.Uuid

  /// Linked category's {@link ai_mall_categories.id} (Systematic domain).
  ai_mall_category_id String @db.Uuid

  /// Order or position in category for custom sort. Example: 1.
