  change_type String

  /// Point amount (earn=positive, redeem=negative, adjust=positive/negative). 3NF atomic.
  amount Int @db.Integer

  /// Explanation for business logic, e.g., 'order_placement' or 'admin_correction'. 3NF atomic, optional.
  reason String?

  /// Created timestamp for audit and ledgers. 1NF atomic.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_mall_customers @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([change_type])
