  // RELATIONS
  //----
  fk_article_comments_article ai_mall_articles @relation(fields: [article_id], references: [id], onDelete: Cascade)
  fk_comments_customer ai_mall_customers? @relation(fields: [author_customer_id], references: [id], onDelete: Cascade)
  fk_comments_seller ai_mall_sellers? @relation(fields: [author_seller_id], references: [id], onDelete: Cascade)
  fk_comments_admin ai_mall_admins? @relation(fields: [author_admin_id], references: [id], onDelete: Cascade)
  fk_comments_parent ai_mall_article_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_mall_article_comments[] @relation("recursive")

  @@index([author_customer_id])
  @@index([author_seller_id])
  @@index([author_admin_id])
  @@index([parent_id])

  @@index([article_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Article category entity - Implements requirement for grouping articles for organization, navigation, filtering, and SEO. Maintains 3NF by separating categorical metadata from articles. For example, guides, news, policy updates, etc. Each category can be assigned to multiple articles. Hierarchy (parent-child) allows nesting categories. Special behaviors: if parent_id is set, forms category tree; else is a root-level category. Application can enforce business logic on parent/child constraints.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_article_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each article category.
  id String @id @db.Uuid

  /// Optional parent category's {@link ai_mall_article_categories.id} for category hierarchy and nesting. Null for root categories.
  parent_id String? @db.Uuid

  /// Category name - Implements the requirement for unique, human-readable article category label. Ensures normalization.
  name String

  /// SEO-friendly category slug for URLs/navigation. Must be unique within categories. Example: 'news-updates'. Maintains normalization by not duplicating category name.
  slug String

  /// Optional category description - Implements meta/SEO or UI tooltip requirement. Nullable, not required.
  description String?

  //----
  // RELATIONS
  //----
  fk_article_categories_parent ai_mall_article_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  ai_mall_articles ai_mall_articles[]
  recursive ai_mall_article_categories[] @relation("recursive")

  @@index([parent_id])

  @@unique([slug])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-11-analytics.prisma:
/// Analytics Event Entity - This implements the requirements for tracking distinct analytics events as demanded in the advanced analytics and AI documentation. 
///
/// Business explanation: Each row represents a single captured analytics event (click, page view, purchase, search, error) generated by any user or system process. Maintains 3NF compliance—event details and context are atomic and not derived. For example, when a customer adds an item to their cart, a new analytics event is created referencing its type and holding contextual payload (serialized JSON). 
///
/// Key relationships: Ties to ai_mall_analytics_event_types for type definition, can reference actor tables (not directly modeled here). 
/// Special behaviors: Loosely coupled with user/session IDs for flexibility; all business logic for attribution is handled externally.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_analytics_events {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each analytics event record.
  id String @id @db.Uuid

  /// Event type reference - Links to event type definition in {@link ai_mall_analytics_event_types.id} to ensure event categorization adheres to system-defined taxonomy. Relationship is required for classification.
  event_type_id String @db.Uuid

  /// Event Occurrence Timestamp - Implements the requirement to record the exact UTC time of the event occurrence. Maintains strict normalization with explicit, unambiguous timestamps. For example, used for all time-based analytics, daily active users, or sequence analysis.
  occurred_at DateTime @db.Timestamptz

  /// Actor Reference (Loose/Flexible) - Optionally associates an event with any system actor (customer, seller, admin). Implements the requirement for user attribution analytics (inferred by external joins). Maintains normalization by not duplicating user state; can be null for system/bot events.
  actor_id String? @db.Uuid

  /// Session Reference (Loose/Flexible) - Optionally attributes the event to a browsing session or device identity for anonymous event tracking. Enforces normalization by keeping only the session UUID here; session metadata is external.
  session_id String? @db.Uuid

  /// Contextual Event Data (JSON/String) - Stores serialized event context payload (click details, product IDs, metadata) as a JSON string field for semi-structured extensibility. Ensures normalization by never repeating structured relations; payload structure is externally enforced. Example: '{"productId": "abc-123", "action": "add_to_cart", "value": 8990 }'.
  context_payload String?

  /// IP Address - Implements the requirement to optionally log origin IP for risk or source analysis. Ensures atomicity by storing only address string. Usage: geo-analytics, fraud investigations, etc.
  ip_address String?

  //----
  // RELATIONS
  //----
  analytics_events_event_type_fk ai_mall_analytics_event_types @relation(fields: [event_type_id], references: [id], onDelete: Cascade)

  ai_mall_user_dashboards ai_mall_user_dashboards?

  @@index([event_type_id, occurred_at])
  @@index([actor_id, occurred_at])
}

/// Analytics Event Type Entity - Implements cataloging all event types (category, action codes) as defined in the advanced analytics system requirements. 
///
/// Business purpose: Each entry defines a logical type of analytics event such as 'page_view', 'add_to_cart', 'purchase', 'error', etc. Maintains 3NF by separating event occurrence from event taxonomy. For example, when a new event type such as 'wishlist_add' is required, it's created here and referenced by all relevant event records. 
///
/// Key relationships: Referenced by events; not directly tied to user/session. 
/// Special behaviors: Type codes and human-readable names must be unique; descriptions provide API and analytics clarity.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_analytics_event_types {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for event type definition.
  id String @id @db.Uuid

  /// Event Type Code - Implements code-based requirement for system-wide event type consistency (e.g., 'page_view', 'add_to_cart'). Must be unique. Maintains normalization by de-coupling event occurrence from type metadata. Example: Used in analytics queries for grouping.
  code String

  /// Event Type Name - Implements requirement for human-readable descriptive name for event type. Example: 'Page View', 'Cart Add'. Supports admin-facing analytics UI lookup.
  name String

  /// Event Type Description - Implements requirement for extended explanation, API tooltip, or audit notes. Maintains normalization by attaching only to type, not to each event.
  description String?

  //----
  // RELATIONS
  //----
  ai_mall_analytics_events ai_mall_analytics_events[]

  @@unique([code])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// User Dashboard Configuration Entity - Implements requirement to let each user (actor) configure personal analytics dashboards as described in analytics and personalization documentation. 
///
/// Business purpose: Each record stores dashboard configuration for a specific user—what widgets or reports are pinned, layout configuration as JSON, and timestamps. Maintains 3NF with atomic user association and configuration payload. Used to persist user dashboard state across sessions and devices.
///
/// Key relationships: References actor ID (can be customer, seller, or admin - stored as UUID; resolving the actual actor is external).
/// Special behaviors: One dashboard config per actor (enforced by unique index); supports time-based filtering and historical layout snapshots.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_user_dashboards {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each dashboard configuration.
  id String @id @db.Uuid

  /// Actor/User Reference - Attributed to a user (any actor type) via system UUID. Ensures every dashboard belongs to exactly one user; resolving actual user is handled in application logic. Not nullable.
  actor_id String @db.Uuid

  /// Dashboard Configuration Payload - Implements storage of widget/report configuration as serialized JSON. Maintains strict normalization as atomic config blob only; no duplicated data. Example: '{"widgets": ["sales_chart", "visits_map"]}'.
  dashboard_payload String

  /// Dashboard Created Timestamp - Date/time of configuration creation. Ensures atomic record for audit trail. Used for query, filtering, and sorting.
  created_at DateTime @db.Timestamptz

  /// Dashboard Updated Timestamp - Last modification time of dashboard. Ensures traceability of configuration changes and auditability.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_dashboards_actor_fk ai_mall_analytics_events @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@unique([actor_id])
  @@index([created_at])
}

/// Campaign Analytics Metrics Entity - Implements requirements for campaign/promotion performance measurement as required by the promotions and analytics documentation. 
///
/// Business purpose: Each row aggregates or stores campaign metrics (impressions, clicks, redemption counts, revenue, cost, ROI) for a specific campaign and date/time bucket. 
/// Maintains 3NF—metrics are always external/per campaign/per period, never pre-calculated totals. Used by seller/admin dashboards and reporting tools.
///
/// Key relationships: References campaign or promotion via UUID (campaign table external to this domain, relationship by UUID only).
/// Special behaviors: Metric records are independent and domain-normalized—never cache/copy derived aggregates. Composite uniqueness enforced by (campaign_id, period_start).
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_campaign_metrics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for campaign metric row.
  id String @id @db.Uuid

  /// Marketing Campaign/Promotion Reference - Associates metric row to a logical campaign/promotion/offer (defined externally). UUID only; campaign metadata resolved externally. Not nullable.
  campaign_id String @db.Uuid

  /// Metrics Period Start - Implements reporting granularity (e.g., daily, hourly) for time series analytics. Enforces normalization with explicit period-bucketed data only. Used in charts and time-based queries.
  period_start DateTime @db.Timestamptz

  /// Impressions Count - Implements raw metric requirement for number of times campaign was displayed. Atomic count (not accumulated). Maintains normalization as primitive numeric fact only.
  impressions Int @db.Integer

  /// Clicks Count - Implements requirement to store number of user clicks on the campaign. Atomic, fully normalized field, not a calculation.
  clicks Int @db.Integer

  /// Redemptions Count - Requirement to track coupon/promotion redemption count. Maintains atomic normalization.
  redemptions Int @db.Integer

  /// Revenue Attributed - Requirement for revenue measurement attributed to campaign. Maintains strict normalization as atomic recorded value (never a calculation or cache).
  revenue Float @db.DoublePrecision

  /// Cost Attributed - Requirement for cost metric (discounts, spend) attributed to campaign. Stored as atomic numeric value (never as a calculated or derived field).
  cost Float @db.DoublePrecision

  /// ROI - Implements requirement to persist measured return on investment for the specific campaign/time. Must be atomic and calculated externally; never duplicated/derived in reporting queries.
  roi Float @db.DoublePrecision

  //----
  // RELATIONS
  //----
  campaign_metrics_campaign_fk ai_mall_campaign_metrics @relation("recursive", fields: [campaign_id], references: [id], onDelete: Cascade)

  recursive ai_mall_campaign_metrics[] @relation("recursive")

  @@unique([campaign_id, period_start])
  @@index([period_start])
}

