schemas.schema-01-systematic.prisma:
/// Platform sales channel configuration - This implements the cross-channel and modular marketplace requirement from 'Architecture & Extensibility (07_ai-mall_architecture-and-extensibility.md)'. Provides foundational separation for mall operations by defining unique sales channels (web, app, third-party). Maintains 3NF structure by keeping channel-specific configuration here, without duplicating in lower-level business tables. Example: creation of a 'BrandA Global Web Store' or 'Mobile App Korea'. Key relationships: Referenced by sections, categories, file usages. Special behaviors: Channel can be disabled without deletion for staged launches or regulatory holds.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique identifier for the sales channel. Implements channel abstraction reference. Allows for lookup and management by business and system APIs. Example: 'KR_WEB', 'US_MOBILE'. Must be unique.
  code String

  /// Human-readable channel label. Example: 'Korea Web Store', 'Global Mobile App'.
  name String

  /// Brand association for multi-brand platforms. Example: 'BrandA', 'GenericMall'.
  brand String?

  /// Whether this channel is currently active/published to users.
  enabled Boolean

  /// Timestamp when the channel was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last channel update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_sections ai_mall_sections[]
  ai_mall_orders ai_mall_orders[]

  @@unique([code])
  @@index([enabled])
}

/// Channel sections configuration - Implements extensible, configurable sections for each sales channel, as described in 'Architecture & Extensibility'. Business purpose: Allows flexible segmentation within a channel (e.g., Electronics, Lifestyle, Flash Sale). Maintains 3NF by holding only section-level config/reference—products/content are managed separately. Example: a channel may have 'Home', 'Deals', or 'Electronics' sections. Key relationships: Links to {@link ai_mall_channels.id}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent channel's {@link ai_mall_channels.id}. Each section is tied to a channel, enforcing modular configuration. Required foreign key association.
  ai_mall_channel_id String @db.Uuid

  /// Unique identifier for section within the channel.
  code String

  /// User-facing section name (e.g., 'Flash Sale', 'Kids').
  name String

  /// Sort order of sections within a channel.
  order Int? @db.Integer

  /// Is this section active and visible on the channel?
  enabled Boolean

  /// Timestamp section was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last section update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_sections_channel ai_mall_channels @relation(fields: [ai_mall_channel_id], references: [id], onDelete: Cascade)

  @@unique([ai_mall_channel_id, code])
  @@index([ai_mall_channel_id])
}

/// Flexible multi-level taxonomy for mall navigation - Implements hierarchical category management from 'Product & Content Management'. Enables unlimited nesting/category grouping for products and content. Maintains strict normalization by keeping category structure atomic and storing only hierarchy metadata here (not product links). Example: creation of 'Electronics > Phones > Smartphones', reordering, reparenting. Key relationships: Optional parent-child self-reference allows tree structure.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent category's {@link ai_mall_categories.id}. Enables recursive taxonomy. Nullable root-level. Maintains hierarchical structure in 3NF.
  parent_id String? @db.Uuid

  /// Unique business identifier for the category. Example: 'ELEC_SMARTPHONES', 'TOYS_OUTDOOR'.
  code String

  /// Display name for category (multi-lingual UI supported at app layer).
  name String

  /// Category nesting depth (e.g., 0=root, 1=child, 2=grandchild).
  level Int @db.Integer

  /// Sort order within siblings.
  order Int? @db.Integer

  /// Is the category active and visible for filtering/browsing?
  enabled Boolean

  /// Timestamp category was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_categories_parent ai_mall_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_mall_categories[] @relation("recursive")
  ai_mall_category_products ai_mall_category_products[]

  @@unique([code])
  @@index([parent_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Attachment and file repository for mall resources - Implements file/media management as in 'Architecture (07_ai-mall_architecture-and-extensibility.md)'. Manages all uploaded files (images, videos, docs), storing metadata but not raw content. Example: product images, manuals, admin banners. Used by products, promotions, articles, etc. Business logic for file lifecycle (expiry, visibility) starts here.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_files {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Permanent location of the file in cloud, CDN, or on-prem storage.
  uri String @db.VarChar(80000)

  /// Original file name with extension.
  name String

  /// Media type (MIME), e.g., 'image/png'.
  type String

  /// File size in bytes.
  size Int @db.Integer

  /// Upload timestamp for audit and security reviews.
  created_at DateTime @db.Timestamptz

  /// Optional expiration/deletion timestamp.
  expires_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_file_usages ai_mall_file_usages[]
  ai_mall_product_images ai_mall_product_images[]

  @@index([type])
  @@index([expires_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Mapping of files to business resources (products, channels, etc.) - Implements domain-agnostic usage log as described in 'Architecture'. Enables the same file to be attached to many business entities across domains, while separate from core file repository. Maintains 3NF: no reference info is stored in ai_mall_files; all usage links and field-specific meta go here. Example: link file id X to 'cover_image' of product Y. Special behaviors: file usage field enables typed attachments.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_file_usages {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced file's {@link ai_mall_files.id}. Required foreign key association.
  ai_mall_file_id String @db.Uuid

  /// Domain of usage, e.g., 'product', 'promotion', 'article'.
  usage_domain String

  /// Specific field context (e.g., 'cover_image').
  usage_field String

  /// UUID of the linked business entity (product, channel, section, etc.).
  entity_id String @db.Uuid

  /// Timestamp usage link was established.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_file_usages_file ai_mall_files @relation(fields: [ai_mall_file_id], references: [id], onDelete: Cascade)

  @@unique([ai_mall_file_id, usage_domain, usage_field, entity_id])
  @@index([usage_domain])
  @@index([entity_id])
}

/// API Gateway registry/coordination - Implements security, endpoint, and routing control as described in 'Architecture'. Records metadata for each API gateway (core, internal, partner, test environments). Maintains 3NF: endpoint/routing data only, logs/stats are segregated elsewhere. Example: 'Public Core Gateway', 'Partner Channel Gateway'. Special behaviors: Gateways can be enabled/disabled for maintenance.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_api_gateways {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique gateway code. Example: 'CORE', 'PARTNER', 'TESTNET'.
  code String

  /// Display name/label for management UI.
  name String

  /// Base endpoint URL (e.g., 'https://api.mall.com/core').
  base_url String @db.VarChar(80000)

  /// Whether this gateway is currently handling traffic.
  enabled Boolean

  /// Timestamp when gateway was added.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last gateway update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([enabled])
}

/// System-wide audit trail for compliance and troubleshooting - Implements audit log requirements from 'Security, Compliance & Accessibility'. Captures every critical action (user, admin, system) in a unified, immutable ledger for security and compliance. Maintains 3NF; audit log is append-only, no business data is duplicated. Example: admin disables a channel, user edits their role. Links actions to actor/entity via actor_id, entity_domain, and entity_id. All cross-table references are soft for extensibility.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Canonical name of action performed (e.g., 'channel_disable').
  action String

  /// Role performing the action (e.g., 'admin', 'seller', 'system').
  actor_role String?

  /// UUID of user/system performing the action.
  actor_id String? @db.Uuid

  /// Entity domain this log references (e.g., 'channel').
  entity_domain String?

  /// UUID of the entity record acted upon.
  entity_id String? @db.Uuid

  /// IP address linked to the action.
  ip String?

  /// Structured or free-form log payload with action metadata/data.
  details String?

  /// Timestamp when the action/log was recorded.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([entity_domain, entity_id])
  @@index([actor_role])
  @@index([created_at])
}

/// Global and module-specific configuration registry - Implements platform-wide and modular configuration patterns from 'Architecture'. Stores key-value config for all mall subsystems (feature flags, UI settings, 3rd-party integration keys). Every setting is a separate row with unique key, value, and optional group/domain. Example: toggling AI segments, maintenance windows. Fully normalized.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Canonical config key (e.g., 'feature/recommendations.enabled').
  key String

  /// Current value for the key (string-encoded for flexibility).
  value String

  /// Configuration domain/group (e.g., 'feature').
  group String?

  /// Optional description for admin UI, change log, or documentation.
  description String?

  /// Timestamp when the key was created.
  created_at DateTime @db.Timestamptz

  /// Last modified time for this key/value.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([group])
}

schemas.schema-02-actors.prisma:
/// Customer accounts - This implements the platform's customer account system from the user role and management requirements. Business users marked as customers for ownership of carts, orders, reviews, and personalization. Maintains 3NF by using normalized foreign keys to auth/user states. For example, a customer making a purchase will be linked here. Key relationships: references user profile, authentication, active state. Special behaviors: only non-admin, non-seller users belong here; customers can transition to seller.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged profile's {@link ai_mall_user_profiles.id}. Profile association for customer details and preference data. Required for linking demographic and personalization info.
  user_profile_id String @db.Uuid

  /// Authentication details {@link ai_mall_authentications.id}. Secures login credentials. Required for SSO, OAuth, multi-factor.
  authentication_id String @db.Uuid

  /// Current state {@link ai_mall_user_states.id}. Shows if active, suspended, pending. Used for soft deletion and compliance audit.
  user_state_id String @db.Uuid

  /// Timestamp of account creation. Implements onboarding flow compliance.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update. Auditing user changes.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profile ai_mall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)
  authentication ai_mall_authentications @relation(fields: [authentication_id], references: [id], onDelete: Cascade)
  user_state ai_mall_user_states @relation(fields: [user_state_id], references: [id], onDelete: Cascade)

  ai_mall_carts ai_mall_carts[]
  ai_mall_orders ai_mall_orders[]
  ai_mall_coupon_issuances ai_mall_coupon_issuances[]
  ai_mall_loyalty_point_ledgers ai_mall_loyalty_point_ledgers[]
  ai_mall_deposits ai_mall_deposits[]
  ai_mall_point_transactions ai_mall_point_transactions[]
  ai_mall_point_balances ai_mall_point_balances?
  ai_mall_inquiries ai_mall_inquiries[]
  ai_mall_inquiry_comments ai_mall_inquiry_comments[]
  ai_mall_reviews ai_mall_reviews[]
  ai_mall_review_comments ai_mall_review_comments[]
  ai_mall_feedbacks ai_mall_feedbacks[]
  ai_mall_favorites ai_mall_favorites[]
  ai_mall_wishlists ai_mall_wishlists[]
  ai_mall_collections ai_mall_collections[]
  ai_mall_article_comments ai_mall_article_comments[]

  @@unique([user_profile_id])
  @@unique([authentication_id])
  @@index([user_state_id])
}

/// Seller accounts - Implements the merchant/seller role from requirements. Seller ownership over storefronts, product listings, and order fulfillment. Maintains 3NF; separated from customer/admin for permissioning. For example, a merchant dashboard references this. Key relationships: links to user profile and authentication. Special behaviors: future role upgrade/downgrade mapping.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged profile's {@link ai_mall_user_profiles.id}. Tied to individual or business profile for seller.
  user_profile_id String @db.Uuid

