  id String @id @db.Uuid

  /// User being assigned {@link ai_mall_user_profiles.id}. User for the assignment. Allows one-to-many mapping (user can have multiple roles over time).
  user_profile_id String @db.Uuid

  /// Assigned role {@link ai_mall_roles.id}. Links assignment to the role entity.
  role_id String @db.Uuid

  /// Timestamp of role assignment creation.
  assigned_at DateTime @db.Timestamptz

  /// Timestamp of role detachment/deactivation (null if still active). Implements access revocation.
  detached_at DateTime? @db.Timestamptz

  /// Human-readable description of the assignment/detachment reason (optional). Used for audit logging.
  reason String?

  //----
  // RELATIONS
  //----
