  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique code identifying the state (e.g., 'active', 'suspended', 'pending', 'deleted'). Used for fast gating and compliance audits.
  code String

  /// Translatable state name ('Active','Suspended','Pending','Deleted'). For admin UIs and user logs.
  name String

  /// Human/long-form description of state. For audit/compliance and admin reference. E.g., when/how state is assigned.
  description String?

  /// Record state creation timestamp.
  created_at DateTime @db.Timestamptz

  /// State record last updated at.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_customers ai_mall_customers[]
  ai_mall_sellers ai_mall_sellers[]
