  @@unique([code])
  @@unique([name])
}

schemas.schema-03-products.prisma:
/// Product master data table - Implements product entity required for catalog, as per requirements analysis (Section 3). 3NF-compliant. Example: Seller creates a product, links variants, images, tags, categories. Key: brand, seller, category, snapshot versioning. Special: Product lifecycle, audit log. Unique: sku, slug.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated brand's {@link ai_mall_brands.id}. Identifies product brand for filtering, analytics, offers.
  ai_mall_brand_id String? @db.Uuid

  /// Product seller's {@link ai_mall_sellers.id}. Links to seller (owner) of the product. Maintains seller's catalog ownership.
  ai_mall_seller_id String @db.Uuid

  /// Stock keeping unit, implements unique product tracking. Example: 'PROD12345'.
  sku String

  /// Product display name. Example: 'Wireless Earbuds'.
  name String

  /// Short product summary, for quick reference.
  description String?

  /// Product state (draft, under_review, published, archived). Example: 'published'.
  status String

  /// Primary image URL. Only main image is here; all other images are in ai_mall_product_images for normalization.
  main_image_url String? @db.VarChar(80000)

  /// SEO meta title. For search optimization.
  meta_title String?

  /// SEO meta description.
  meta_description String?

  /// Unique SEO slug for product page URL. Example: 'wireless-earbuds-2025'.
  slug String

  /// Creation timestamp. For audit/data lineage traceability.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion marker. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  BrandProduct ai_mall_brands? @relation(fields: [ai_mall_brand_id], references: [id], onDelete: Cascade)
  SellerProduct ai_mall_sellers @relation(fields: [ai_mall_seller_id], references: [id], onDelete: Cascade)

  ai_mall_product_variants ai_mall_product_variants[]
  ai_mall_product_images ai_mall_product_images[]
  ai_mall_product_tags ai_mall_product_tags[]
  ai_mall_product_attributes ai_mall_product_attributes[]
  ai_mall_category_products ai_mall_category_products[]
  ai_mall_product_snapshots ai_mall_product_snapshots[]
  ai_mall_cart_items ai_mall_cart_items[]
  ai_mall_inquiries ai_mall_inquiries[]
  ai_mall_reviews ai_mall_reviews[]
  ai_mall_favorites ai_mall_favorites[]
  ai_mall_wishlist_items ai_mall_wishlist_items[]
  ai_mall_collection_items ai_mall_collection_items[]

  @@index([ai_mall_brand_id])

  @@unique([sku])
  @@unique([slug])
  @@index([ai_mall_seller_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([meta_title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product variant detail table - Implements variant logic (multi-dimensional SKUs, Section 5). Stores atomic option values (e.g., color, size), price, stock per variant. Maintains 3NF. Example: 'Red/Small', 'Blue/Large'. Relationships: main product and inventory. Uniqueness: per product, audit trail via timestamps.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
