schemas.schema-04-carts.prisma:
/// Shopping Cart entity - This implements the persistent multi-seller, cross-device cart requirement from the requirements document (see 04_ai-mall_cart-and-order-processing.md, 'Cart Management'). 
///
/// This model stores a customer's current shopping cart, supporting persistent and session-based cart recovery. Maintains 3NF compliance: only core atomic cart attributes are stored, with all related items separated into ai_mall_cart_items. For example, a user logs in from any device and retrieves a unique cart instance. 
///
/// Key relationships: One-to-many with {@link ai_mall_cart_items} (cart items), many-to-one with {@link ai_mall_customers} (cart owner, from Actors domain), and optional link to {@link ai_mall_cart_sessions} (enables device/session association). 
/// Special behaviors: Soft deletion via 'deleted_at', automatic restoration logic during login/session merge.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the cart instance.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_customers.id}; identifies the cart owner. Implements cross-device and session merge logic.
  ai_mall_customer_id String @db.Uuid

  /// Optional link to shopping session {@link ai_mall_cart_sessions.id}. Used for session-persistent/guest carts before user login/merge. Nullable.
  ai_mall_cart_session_id String? @db.Uuid

  /// Cart creation timestamp - Implements audit/logging requirement. Represents when the cart was first created by the user or system. 3NF compliance: atomic event date only.
  created_at DateTime @db.Timestamptz

  /// Cart last modified timestamp - Required for supporting auto-sync and concurrency control (e.g., real-time cart merging). 3NF compliance: captures only last update event.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for recoverable cart deletion. Implements audit-log and logical delete without physical removal. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_carts_customer_id ai_mall_customers @relation(fields: [ai_mall_customer_id], references: [id], onDelete: Cascade)
  fk_ai_mall_carts_cart_session_id ai_mall_cart_sessions? @relation(fields: [ai_mall_cart_session_id], references: [id], onDelete: Cascade)

  ai_mall_cart_items ai_mall_cart_items[]

  @@index([ai_mall_cart_session_id])

  @@unique([ai_mall_customer_id])
  @@index([created_at])
  @@index([updated_at])
}

/// Shopping Cart Item entity - This implements persistent, multi-product-item cart tracking, enabling dynamic update/merge logic per 04_ai-mall_cart-and-order-processing.md ('Cart Management', 'Real-time validation of inventory, dynamic pricing, and discount eligibility').
///
/// Stores precise entries for each product/variant in a cart. Maintains strict 3NF by storing only atomic item attributes; product/variant details are referenced, never duplicated. For example, each line in the cart—product + variant + quantity + pricing context—is an entry here.
///
/// Key relationships: Many-to-one with {@link ai_mall_carts} (cart header), references {@link ai_mall_products} and {@link ai_mall_product_variants} (from Products domain) for the selected product version, and links back to customers through the cart. 
/// Special behaviors: Supports atomic updates per item; does not cache pricing, stock, or totals (calculated at checkout/time-of-use).
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_cart_items {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a cart line item.
  id String @id @db.Uuid

  /// Belonged cart's {@link ai_mall_carts.id}. Ensures item grouping to a specific persistent or session cart.
  ai_mall_cart_id String @db.Uuid

  /// Product ({@link ai_mall_products.id}) added to the cart—foreign key to Products domain. Only atomic product id is tracked; all product details are externalized for 3NF.
  ai_mall_product_id String @db.Uuid

  /// Product variant ({@link ai_mall_product_variants.id}) selected in cart. Implements fine-grained inventory and pricing per variant, never duplicated here (3NF).
  ai_mall_product_variant_id String? @db.Uuid

  /// Quantity of selected product/variant in the cart. 3NF: atomic count only. For example, 2 means 'user wants two of this variant'. Must be positive integer, enforced at application layer.
  quantity Int @db.Integer

  /// Timestamp when item was first added to cart. For concurrency control and audit logs. 3NF: atomic event time.
  added_at DateTime @db.Timestamptz

  /// Timestamp when item was last updated (e.g., quantity changed). Supports multi-session merge, audit trail. 3NF: atomic update time only.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_cart_items_cart_id ai_mall_carts @relation(fields: [ai_mall_cart_id], references: [id], onDelete: Cascade)
  fk_ai_mall_cart_items_product_id ai_mall_products @relation(fields: [ai_mall_product_id], references: [id], onDelete: Cascade)
  fk_ai_mall_cart_items_product_variant_id ai_mall_product_variants? @relation(fields: [ai_mall_product_variant_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_product_id])
  @@index([ai_mall_product_variant_id])

  @@unique([ai_mall_cart_id, ai_mall_product_id, ai_mall_product_variant_id])
  @@index([added_at])
  @@index([updated_at])
}

/// Cart Session entity - Implements the guest/anonymous shopping session persistence per requirements (04_ai-mall_cart-and-order-processing.md: 'Cart Management', 'Session resilience').
///
/// Tracks session-specific shopping carts for users who have not signed in, supporting cart restoration on reconnect/crash recovery. Maintains 3NF: atomic cart-session mapping only; all business logic occurs at application layer.
///
/// Key relationships: May be linked by {@link ai_mall_carts}, allowing a session cart to be merged into a user's cart on login (one-to-many or one-to-one depending on user flow).
/// Special behaviors: May be cleaned up on session expiry; soft-deleted via 'deleted_at'.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_cart_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the cart session.
  id String @id @db.Uuid

  /// Unique browser/device/session identifier, typically a secure random string or UUID. Used for mapping anonymous carts, preserving session state across reconnects. 3NF: atomic value only.
  session_key String

  /// Timestamp when session was created. Used for session lifecycle and audit.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this cart session was last used or modified. Enables cleanup and status tracking.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null if session active. Implements safe lifecycle and recovery logic.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_carts ai_mall_carts[]

  @@unique([session_key])
  @@index([created_at])
  @@index([updated_at])
}

schemas.schema-05-orders.prisma:
/// Order Entity - This implements the order tracking and management requirements from the requirements analysis (primarily from Cart & Order Processing and referenced in Promotions/Loyalty logic). 
///
/// This model records the core details of a transaction (customer, seller, order status, channel, timestamps). Maintains strict 3NF compliance: all item/product/fulfillment/payment detail is normalized into related tables. Example: a customer places an order spanning multiple sellers; each order instance is tracked here, referencing customer, channel, and initial status. 
///
/// Key relationships: Links to customer (Actors), seller (Actors), order status, channel (Systematic), and supports referencing payments and fulfillments. Special behaviors: immutable order_id, stateful via status referencing, all denormalized (summaries, counted totals) reside in separate materialized views only.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each order record.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_customers.id} - customer placing the order.
  ai_mall_customer_id String @db.Uuid

  /// Belonged seller's {@link ai_mall_sellers.id} - seller fulfilling this order split (multi-seller support).
  ai_mall_seller_id String @db.Uuid

  /// Related channel's {@link ai_mall_channels.id} - sales channel on which the order was placed.
  ai_mall_channel_id String @db.Uuid

  /// Current order status {@link ai_mall_order_statuses.id} - points to order state (placed, paid, shipped, etc).
  ai_mall_order_status_id String @db.Uuid

  /// External Order Code - Implements third-party channel or system code assignment, used for reconciliation with partners/logistic systems. Normalization is kept by not duplicating core IDs, only allowing system-of-record pointers here. Example: Shopify order code.
  external_order_code String?

  /// Gift Indicator - Implements requirement to track if order is a gift (special instructions on fulfillment/delivery). 3NF is maintained: related detail/notes handled via fulfillment or snapshot entities.
  gift Boolean

  /// Customer Order Memo - Implements capturing of purchase comment/request. Normalized: only memo, not aggregation or status flags. Example: 'Please deliver after 6pm'.
  buy_request_memo String?

  /// Order creation timestamp. Implements requirement for auditability and time-based querying. 3NF is kept by not storing derivative or summary values.
  created_at DateTime @db.Timestamptz

  /// Order updated/modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for audit/history compliance. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_mall_customers @relation(fields: [ai_mall_customer_id], references: [id], onDelete: Cascade)
  seller ai_mall_sellers @relation(fields: [ai_mall_seller_id], references: [id], onDelete: Cascade)
  channel ai_mall_channels @relation(fields: [ai_mall_channel_id], references: [id], onDelete: Cascade)
  order_status ai_mall_order_statuses @relation(fields: [ai_mall_order_status_id], references: [id], onDelete: Cascade)

  ai_mall_order_items ai_mall_order_items[]
  ai_mall_order_snapshots ai_mall_order_snapshots[]
  ai_mall_order_payments ai_mall_order_payments[]
  ai_mall_order_fulfillments ai_mall_order_fulfillments[]
  ai_mall_order_fraud_flags ai_mall_order_fraud_flags[]
  ai_mall_coupon_usages ai_mall_coupon_usages[]
  ai_mall_inquiries ai_mall_inquiries[]
  ai_mall_reviews ai_mall_reviews[]

  @@index([ai_mall_seller_id])
  @@index([ai_mall_order_status_id])

  @@unique([external_order_code])
  @@index([ai_mall_customer_id, created_at])
  @@index([ai_mall_channel_id, created_at])
}

/// Order Item Entity - Implements the requirement to record normalized line item details for each order, per item/SKU, covering the structure outlined in Cart & Order Processing functional requirements. Strictly 3NF: product info/entity reference only, no denormalized rollups or calculations.
///
/// Business purpose: Each record is a unique product (and variant) ordered, with quantity, price, and per-item status. Example: Order containing 2 products generates 2 records here. Key relationships: links to ai_mall_orders, ai_mall_product_variants (Products), ai_mall_order_statuses. Special behaviors: separate status per item for partial fulfillment, references all by foreign key.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each order item.
  id String @id @db.Uuid

  /// Reference to parent order's {@link ai_mall_orders.id}.
  ai_mall_order_id String @db.Uuid

  /// Product variant SKU's {@link ai_mall_product_variants.id}.
  ai_mall_product_variant_id String @db.Uuid

  /// Status of this order item {@link ai_mall_order_statuses.id}. Enables split fulfillment or returns per item.
  ai_mall_order_status_id String @db.Uuid

  /// Quantity ordered - directly implements required per-SKU quantity tracking and normalization by separating item quantities to rows, not as aggregates. Example: 3 of SKU X, 2 of SKU Y across 2 rows.
  requested_quantity Int @db.Integer

  /// Confirmed Price - Business meaning: price per item (including discounts) set at the time of order item confirmation. Complies with 3NF as all calculations reside in reporting/materialized views.
  confirmed_price Float @db.DoublePrecision

  /// Currency of confirmed_price (e.g., USD, KRW). 3NF: currency stored per item for multi-currency support without denormalization.
  confirmed_currency String

  /// Product Title at Time of Order - Implements audit-traceable ordering (snapshot pattern). Normalized: Stores only the business-facing title as it existed at order time.
  product_title_snapshot String

  //----
  // RELATIONS
  //----
  order ai_mall_orders @relation(fields: [ai_mall_order_id], references: [id], onDelete: Cascade)
  product_variant ai_mall_product_variants @relation(fields: [ai_mall_product_variant_id], references: [id], onDelete: Cascade)
  order_status ai_mall_order_statuses @relation(fields: [ai_mall_order_status_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_product_variant_id])

  @@index([ai_mall_order_id])
  @@index([ai_mall_order_status_id])
}

/// Order Status Entity - Implements requirement for flexible, auditable order state tracking per order and per item. All business logic around order state transitions relies on these enumerations. Normalized: no aggregate or rollup data. Example: 'placed', 'paid', 'shipped', 'completed', 'cancelled', etc.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_order_statuses {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each order status.
  id String @id @db.Uuid

  /// Status Code - Short machine-friendly identifier (e.g., placed, paid, shipped, cancelled) supporting business rules. Normalization: Used by foreign-key reference, not duplicated in other tables.
  code String

  /// Status Display Label (user-facing string) - Implements multi-language/locale friendly display. Normalized by keeping locale-specific data in separate translation/supporting tables.
  label String

  /// Long-form business description for the status - implements audit and UI display requirements.
  description String?

  /// Creation timestamp, supporting audit/log requirements.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_orders ai_mall_orders[]
  ai_mall_order_items ai_mall_order_items[]

  @@unique([code])
  @@index([label(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Order Snapshot Entity - Implements full audit-traceable and temporal storage for version history (requirement: snapshot pattern for order editing/auditing). Each record represents an immutable version of an order at a point in time. 3NF: no rollups, denormalized reporting, or calculated values here; only atomic snapshots at the time of update or significant event.
///
/// Business purpose: Enables rollback and change tracking. Example: changing shipping address triggers creation of a new snapshot. Links to parent order and stores who/what/when for inspections/audits.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_order_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each order snapshot.
  id String @id @db.Uuid

  /// Parent order's {@link ai_mall_orders.id} - reference to the order whose state is snapshot.
  ai_mall_order_id String @db.Uuid

  /// Reference admin actor's {@link ai_mall_admins.id} - identifies who/what made the order edit or override.
  ai_mall_admin_id String? @db.Uuid

  /// Immutable JSON snapshot of the order state and details at this point in time. Normalization is maintained by not storing reporting/derived information, only the original state. Example: Change in fulfillment state, item list, or pricing structure all stamped atomically here.
  snapshot_json String

  /// Snapshot creation timestamp. Supports time-travel queries and audit logs.
  created_at DateTime @db.Timestamptz

  /// Editor note, reason, or comment about why the snapshot was saved.
  note String?

  //----
  // RELATIONS
  //----
  order ai_mall_orders @relation(fields: [ai_mall_order_id], references: [id], onDelete: Cascade)
  admin ai_mall_admins? @relation(fields: [ai_mall_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_admin_id])

  @@index([ai_mall_order_id, created_at])
}

/// Order Payment Entity - Implements requirement from Payment Processing: stores individual payment events per order (cash/credit/point/etc), split payments, and refunds. 3NF: atomic payment events only, all aggregation handled in reporting.
///
/// Business purpose: Handles multiple payment attempts per order (installments, refunds), tracks method, amount, and status. Example: User pays half by card, half by points = 2 payment records. Key relationships: Links to ai_mall_orders, payment method, and admin (verified or managed by).
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_order_payments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each payment record.
  id String @id @db.Uuid

  /// Reference to order's {@link ai_mall_orders.id} - the order being paid/refunded.
  ai_mall_order_id String @db.Uuid

  /// If manually processed or confirmed, admin actor's {@link ai_mall_admins.id}.
  ai_mall_admin_id String? @db.Uuid

  /// Payment Method Code - Implements business logic around payment types: card, cash, deposit, point, etc. Normalized: only short code, details in other structures or policies.
  payment_method String

  /// Exact paid amount for this payment event. Normalized: no aggregation or reporting fields.
  paid_amount Float @db.DoublePrecision

  /// Currency code for paid_amount (e.g., USD, KRW).
  paid_currency String

  /// Current status of payment (e.g., pending, completed, failed). May reference future status enum/extensions.
  payment_status String

  /// External or gateway transaction reference ID.
  payment_transaction_id String?

  /// Timestamp when payment was processed/received (atomic event).
  paid_at DateTime @db.Timestamptz

  /// Additional comment or admin note for this payment event.
  note String?

  /// Payment record creation timestamp for audit/tracing.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order ai_mall_orders @relation(fields: [ai_mall_order_id], references: [id], onDelete: Cascade)
  admin ai_mall_admins? @relation(fields: [ai_mall_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_admin_id])

  @@index([ai_mall_order_id, created_at])
}

/// Order Fulfillment Entity - Implements fulfillment tracking required for each order (shipping, delivery, pickup, etc). This is strictly normalized (3NF), with all summary data (e.g., delivery times, ship addresses) snapshotted for audit/history only.
///
/// Business purpose: Each record tracks one fulfillment event: outbound, return, partial, correction, etc. Supports multi-stage or split fulfillment. Example: 1 Order, 2 shipments. Key relationships: Links to ai_mall_orders, admin (actor), references external shipper/courier via external fields only.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_order_fulfillments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique fulfillment event.
  id String @id @db.Uuid

  /// Parent order's {@link ai_mall_orders.id} - the order being fulfilled.
  ai_mall_order_id String @db.Uuid

  /// Admin actor's {@link ai_mall_admins.id} if fulfillment was manually recorded or overseen.
  ai_mall_admin_id String? @db.Uuid

  /// Type of fulfillment event (e.g., shipping, in-store pickup, return, exchange).
  fulfillment_type String

  /// Quantity fulfilled in this event (supports partial and staged fulfillments/returns).
  fulfilled_quantity Int @db.Integer

  /// External courier or logistics provider code. Implements API/data exchange compliance without denormalizing shipment info in regular tables.
  external_courier_code String?

  /// Package tracking number assigned by courier (for customer/state/reference).
  tracking_number String?

  /// Timestamp when fulfillment was completed/carried out.
  fulfilled_at DateTime @db.Timestamptz

  /// Fulfillment record's creation timestamp for audit/history purposes.
  created_at DateTime @db.Timestamptz

  /// Free-form comment, reason, or admin note for this fulfillment event.
  memo String?

  //----
  // RELATIONS
  //----
  order ai_mall_orders @relation(fields: [ai_mall_order_id], references: [id], onDelete: Cascade)
  admin ai_mall_admins? @relation(fields: [ai_mall_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_admin_id])

  @@index([ai_mall_order_id, fulfilled_at])
}

/// Order Fraud Flag Entity - Implements the AI-driven fraud detection and manual override requirements from Cart & Order Processing and Analytics. 3NF is kept by storing each flag as a normalized record (not as aggregate or summary).
///
/// Business purpose: Each record is a fraud alert, risk score, or manual override for an order. Example: AI detects high risk; flag is set with score/status/reason. Key relationships: linked to ai_mall_orders, ai_mall_admins (if acted on), with timestamps and audit trail.
///
/// Special behaviors: Rigorous auditability. No denormalized metrics (counts/totals) are stored here – all reporting is handled externally or in mv_/analytics tables.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_order_fraud_flags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique fraud flag record.
  id String @id @db.Uuid

  /// Order's {@link ai_mall_orders.id} that is suspected or flagged.
  ai_mall_order_id String @db.Uuid

  /// Admin's {@link ai_mall_admins.id} if flag is set/acknowledged manually.
  ai_mall_admin_id String? @db.Uuid

  /// Type of flag (e.g., ai_detected, manual, cleared, investigation).
  flag_type String

  /// Numerical risk score assigned by AI or manual review. Normalization: calculated values or rollups are stored only in analytics, not here.
  risk_score Float @db.DoublePrecision

  /// Current status of the fraud flag (e.g., active, resolved, dismissed).
  status String

  /// Textual reason or explanation why this flag was set (free-form or code references).
  reason String?

  /// Flag record's creation timestamp for historical/audit compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order ai_mall_orders @relation(fields: [ai_mall_order_id], references: [id], onDelete: Cascade)
  admin ai_mall_admins? @relation(fields: [ai_mall_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_admin_id])

  @@index([ai_mall_order_id])
}

schemas.schema-06-coupons.prisma:
/// Promotion Campaigns - Implements core promotional campaign, sale event, and discount activities from the promotions and loyalty system documentation. Keeps campaigns atomic and normalized (3NF), supporting scheduling, activation, deactivation, and analytic tracing. This table has no calculated fields and is referenced by coupons. Example use: "Summer Sale" applied across listed categories.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_promotions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each promotion campaign.
  id String @id @db.Uuid

  /// Title of the promotion event for user display. Example: 'Summer Sale'. 1NF atomic.
  title String

  /// Detailed description for analytics and user understanding. For example, '10% off all orders over $50'.
  description String?

  /// When promotion is scheduled to begin. 3NF, atomic.
  start_at DateTime @db.Timestamptz

  /// When promotion is scheduled to end. 3NF, atomic.
  end_at DateTime @db.Timestamptz

  /// If this promotion is currently active. Support for dynamic toggling. 1NF atomic.
  active Boolean

  /// Created timestamp for audit trail. 1NF atomic.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for history trace. 1NF atomic.
  updated_at DateTime @db.Timestamptz

  /// Soft delete for compliance. 3NF atomic, null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_coupons ai_mall_coupons[]

  @@unique([title])
  @@index([active])
  @@index([start_at, end_at])
}

/// Coupons - Implements business requirements for code-based campaign offers as per promotions and loyalty system documentation. Supports stackable/exclusive coupon logic with enforced normalization. Example: 'WELCOME10' code for first order discount. Coupons can be linked to promotions and issued individually through coupon issuances. This model maintains referential integrity with ai_mall_promotions where 'promotion_id' is set, holding no calculated fields. 3NF compliance.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each coupon.
  id String @id @db.Uuid

  /// Associated promotion's ai_mall_promotions.id. Links the coupon to a high-level marketing event. May be null for one-off coupons. Referential integrity to ai_mall_promotions.
  promotion_id String? @db.Uuid

  /// Unique coupon code for redemption (e.g., 'SUMMER2025'). 1NF atomic.
  code String

  /// Description of coupon offer logic. Used for customer-facing messaging and analytics.
  description String?

  /// Coupon type, e.g. percentage/fixed/free_shipping. Used for validation logic. 1NF atomic.
  type String

  /// Discount value for the coupon, as per type. 1NF atomic.
  value Float @db.DoublePrecision

  /// Minimum spend required to activate this coupon. 3NF atomic (null if inapplicable).
  min_purchase_amount Float? @db.DoublePrecision

  /// Maximum number of global redemptions for coupon (anti-abuse control). 1NF atomic.
  usage_limit Int? @db.Integer

  /// Allowed usage count per user (anti-abuse control). 3NF atomic, null = unlimited.
  per_user_limit Int? @db.Integer

  /// Coupon usable from this time (for scheduling window). 1NF atomic.
  valid_from DateTime @db.Timestamptz

  /// Date/time coupon expires. 1NF atomic.
  valid_until DateTime @db.Timestamptz

  /// Whether this coupon can be combined with others. 1NF atomic.
  stackable Boolean

  /// Whether coupon must be used alone (enforced exclusivity). 3NF atomic.
  exclusive Boolean

  /// If this coupon is currently enabled in the system (admin toggling). 1NF atomic.
  enabled Boolean

  /// Created timestamp. 1NF atomic.
  created_at DateTime @db.Timestamptz

  /// Updated timestamp. 1NF atomic.
  updated_at DateTime @db.Timestamptz

  /// Soft delete for audit/compliance. 3NF, null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  promotion ai_mall_promotions? @relation(fields: [promotion_id], references: [id], onDelete: Cascade)

  ai_mall_coupon_issuances ai_mall_coupon_issuances[]

  @@unique([code])
  @@index([promotion_id])
  @@index([type])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Coupon Issuance Records - Represents every instance where a coupon is issued/granted to a particular user for redemption tracking, audit, and analytics. 3NF-compliant. Links to coupons and users, supporting anti-abuse and compliance tracks. Example: Record for single-user coupon issued to attract new customer.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_coupon_issuances {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each coupon issuance instance.
  id String @id @db.Uuid

  /// Coupon identifier (ai_mall_coupons.id). Links issuance to its coupon for validation and audit. Referential integrity enforced.
  coupon_id String @db.Uuid

  /// Issued-to user identifier (ai_mall_customers.id, external). Required for personalized coupon assignment. Referential integrity to external users table.
  user_id String @db.Uuid

  /// When this coupon was issued. Used for redemption and audit trails. 1NF atomic.
  issued_at DateTime @db.Timestamptz

  /// Date/time this issued coupon expires (may differ from coupon's global expiry). 3NF atomic.
  expires_at DateTime @db.Timestamptz

  /// Flag for usage status. True if user redeemed, else False. 1NF atomic.
  redeemed Boolean

  /// Creation time (audit/compliance). 1NF atomic.
  created_at DateTime @db.Timestamptz

