  customer ai_mall_customers @relation(fields: [ai_mall_customer_id], references: [id], onDelete: Cascade)

  ai_mall_wishlist_items ai_mall_wishlist_items[]

  @@unique([ai_mall_customer_id, name])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
