  ai_mall_wishlist_id String @db.Uuid

  /// Wish-listed Product's {@link ai_mall_products.id}
  ai_mall_product_id String @db.Uuid

  /// Timestamp when the item was added to the wishlist.
  created_at DateTime @db.Timestamptz

