schemas.schema-01-systematic.prisma:
/// Platform sales channel configuration - This implements the cross-channel and modular marketplace requirement from 'Architecture & Extensibility (07_ai-mall_architecture-and-extensibility.md)'. Provides foundational separation for mall operations by defining unique sales channels (web, app, third-party). Maintains 3NF structure by keeping channel-specific configuration here, without duplicating in lower-level business tables. Example: creation of a 'BrandA Global Web Store' or 'Mobile App Korea'. Key relationships: Referenced by sections, categories, file usages. Special behaviors: Channel can be disabled without deletion for staged launches or regulatory holds.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique identifier for the sales channel. Implements channel abstraction reference. Allows for lookup and management by business and system APIs. Example: 'KR_WEB', 'US_MOBILE'. Must be unique.
  code String

  /// Human-readable channel label. Example: 'Korea Web Store', 'Global Mobile App'.
  name String

  /// Brand association for multi-brand platforms. Example: 'BrandA', 'GenericMall'.
  brand String?

  /// Whether this channel is currently active/published to users.
  enabled Boolean

  /// Timestamp when the channel was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last channel update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_sections ai_mall_sections[]
  ai_mall_orders   ai_mall_orders[]

  @@unique([code])
  @@index([enabled])
}

/// Channel sections configuration - Implements extensible, configurable sections for each sales channel, as described in 'Architecture & Extensibility'. Business purpose: Allows flexible segmentation within a channel (e.g., Electronics, Lifestyle, Flash Sale). Maintains 3NF by holding only section-level config/reference—products/content are managed separately. Example: a channel may have 'Home', 'Deals', or 'Electronics' sections. Key relationships: Links to {@link ai_mall_channels.id}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent channel's {@link ai_mall_channels.id}. Each section is tied to a channel, enforcing modular configuration. Required foreign key association.
  ai_mall_channel_id String @db.Uuid

  /// Unique identifier for section within the channel.
  code String

  /// User-facing section name (e.g., 'Flash Sale', 'Kids').
  name String

  /// Sort order of sections within a channel.
  order Int? @db.Integer

  /// Is this section active and visible on the channel?
  enabled Boolean

  /// Timestamp section was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for the last section update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_mall_sections_channel ai_mall_channels @relation(fields: [ai_mall_channel_id], references: [id], onDelete: Cascade)

  @@unique([ai_mall_channel_id, code])
  @@index([ai_mall_channel_id])
}

/// Flexible multi-level taxonomy for mall navigation - Implements hierarchical category management from 'Product & Content Management'. Enables unlimited nesting/category grouping for products and content. Maintains strict normalization by keeping category structure atomic and storing only hierarchy metadata here (not product links). Example: creation of 'Electronics > Phones > Smartphones', reordering, reparenting. Key relationships: Optional parent-child self-reference allows tree structure.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent category's {@link ai_mall_categories.id}. Enables recursive taxonomy. Nullable root-level. Maintains hierarchical structure in 3NF.
  parent_id String? @db.Uuid

  /// Unique business identifier for the category. Example: 'ELEC_SMARTPHONES', 'TOYS_OUTDOOR'.
  code String

  /// Display name for category (multi-lingual UI supported at app layer).
  name String

  /// Category nesting depth (e.g., 0=root, 1=child, 2=grandchild).
  level Int @db.Integer

  /// Sort order within siblings.
  order Int? @db.Integer

  /// Is the category active and visible for filtering/browsing?
  enabled Boolean

  /// Timestamp category was created.
  created_at DateTime @db.Timestamptz

