  @@index([ai_mall_brand_id])
  @@index([ai_mall_seller_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([meta_title(ops: raw("gin_trgm_ops"))], type: Gin)
