  /// Order identifier (ai_mall_orders.id, external) for which coupon applied. Referential integrity to external orders table.
  order_id String @db.Uuid

  /// When the coupon was redeemed. 1NF atomic.
  used_at DateTime @db.Timestamptz

  /// Creation time for audit. 1NF atomic.
  created_at DateTime @db.Timestamptz

  /// Update time for audit/audit trail. 1NF atomic.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for compliance/audit. 3NF, null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  issuance ai_mall_coupon_issuances @relation(fields: [issuance_id], references: [id], onDelete: Cascade)
