schemas.schema-07-coins.prisma:
/// Point Transaction Ledger - This implements the platform's requirement for a reliable, immutable audit trail of all point-related activities as outlined in the loyalty/promotion and auditing sections of the requirements (see 05_ai-mall_promotions-and-loyalty-systems.md and 09_ai-mall_security-compliance-accessibility.md).
///
/// Tracks every accrual, redemption, or adjustment of loyalty/mileage points for any user. Maintains 3NF normalization by modeling each transaction atomically (no aggregate fields, only point deltas per event). Example: when a customer earns points from an order, or redeems points at checkout, a row is created here. Supports full historical tracing for reversals, fraud investigation, and compliance/audit purposes.
///
/// Key relationships: references user (foreign key, e.g., ai_mall_customers.id), optionally associates to order or coupon, references rule for why points were changed. Special behavior: rows are immutable for audit; reversal is modeled as a new, opposite-amount transaction.
///
/// @namespace Coins
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_point_transactions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each point transaction.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_customers.id}. The user who owns this point transaction.
  ai_mall_customer_id String @db.Uuid

  /// Applied rule's {@link ai_mall_point_rules.id}. The business rule (e.g., reason or campaign) under which the points were created/consumed.
  ai_mall_point_rule_id String @db.Uuid

  /// Type of transaction - Implements point event reason mapping. E.g., 'accrual' for earning, 'redemption' for spend, 'reversal', etc. Ensures normalization by storing atomic event type rather than embedding logic.
  change_type String

  /// Points added/subtracted. Always positive; sign (+/-) determines addition or subtraction. Enforces atomic point changes for each event.
  amount Int @db.Integer

  /// Optional transaction detail for user-facing logs or admin/audit review. Maps to enhanced auditability requirement.
  description String?

  /// Transaction creation timestamp. Immutable, ensures strict order and unique event log. Used for audit, chronological tracing, balance calculation.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_point_transactions_customer ai_mall_customers   @relation(fields: [ai_mall_customer_id], references: [id], onDelete: Cascade)
  fk_point_transactions_rule     ai_mall_point_rules @relation(fields: [ai_mall_point_rule_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_point_rule_id])
  @@index([ai_mall_customer_id, created_at])
}

/// Point Rule Definitions - Implements the need for flexible, traceable point accrual/redemption business logic (see 05_ai-mall_promotions-and-loyalty-systems.md).
///
/// Stores the definition and configuration of all point-related rules and campaigns (e.g., 'Earn 2 points per $1 at category X', 'Birthday bonus', 'Refund adjustment'). Maintains normalization by separating rule logic from transaction and balance. Example: each time a point action occurs, it references a rule row here (either a standard accrual, event promo, or manual adjustment).
///
/// Key relationships: referenced by point transactions. Special behaviors: rules can be activated/deactivated, may include metadata/config for automation, can be time-bounded (start/end).
///
/// @namespace Coins
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_point_rules {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each point rule.
  id String @id @db.Uuid

  /// Unique code for rule. Implements requirement for auditable, human/machine readable business identifiers (e.g., 'JOIN_BONUS2025'). 3NF: allows easy rule lookup without denormalization.
  rule_code String

  /// Display name for the rule. Maps to business compliance and admin UI/analytics display requirements.
  name String

  /// Detailed explanation of the rule/logic (for admin/audit/UIs).
  description String?

  /// Is the rule currently in effect? Implements enable/disable flows for promotions and regulatory compliance. 3NF: no redundancy; just binary flag.
  active Boolean

  /// Rule effect start time. Allows time-based, scheduled point actions/promos. Nullable if always active.
  start_at DateTime? @db.Timestamptz

  /// Rule effect end time. Nullable if open-ended or permanent rule.
  end_at DateTime? @db.Timestamptz

  /// Optional JSON metadata for extensibility (e.g., custom rule configs, dynamic parameters).
  metadata String?

  //----
  // RELATIONS
  //----
  ai_mall_point_transactions ai_mall_point_transactions[]

  @@unique([rule_code])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Point Balances by User - Implements the requirement for instant user dashboard display of current point status (see promotions/loyalty UX guidelines). Serves as the current 'materialized' view of all point transactions, but fully normalized (not a denormalized/cached sum—actual materialized views would use 'mv_' prefix and only for reporting/performance).
///
/// Stores a user's current available (spendable) and pending (e.g., under review or lock-up) point balances. All balance changes derive exclusively from transactions (no manual updates permitted). Example: when a user earns or spends points, after successful transaction insert, this table is atomically updated. Key for customer UX, checkout validation, loyalty dashboards.
///
/// Key relationships: references ai_mall_customers (user), but does not duplicate history. Special behaviors: 1:1 with user; business rules prohibit negative available balances.
///
/// @namespace Coins
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_point_balances {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each user's balance row.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_customers.id}. One row per customer (1:1 constraint).
  ai_mall_customer_id String @db.Uuid

  /// Current available (spendable) point balance. 0 or positive integer, always derived from transaction history. No redundancy—enforces normalization.
  available_points Int @db.Integer

  /// Points pending (e.g., earned but not cleared, or locked). 0 or positive integer, never negative. Separation enables precise deduction flows, as required for order and refund handling. No aggregation/pre-calculation in this table; always normalized.
  pending_points Int @db.Integer

  /// Last update timestamp for balance record. For concurrency control and user/account dashboard accuracy logging. Only updated on legitimate balance change event.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_point_balances_customer ai_mall_customers @relation(fields: [ai_mall_customer_id], references: [id], onDelete: Cascade)

  @@unique([ai_mall_customer_id])
}

schemas.schema-08-inquiries.prisma:
/// [Inquiry] Implements inquiry registration in the Interaction & Personalization requirements. Allows customers to submit questions regarding products or orders, visible to sellers and optionally admins. Maintains 3NF via FKs to customer/product/order. Example: Customer asks if a product ships internationally, seller/admin responds via comments. Key relationships: ai_mall_customers, ai_mall_products, ai_mall_orders; commented via ai_mall_inquiry_comments.
///
/// @namespace Inquiries
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_inquiries {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_customers.id}. Authorship trace and follow-up.
  customer_id String @db.Uuid

  /// Related product's {@link ai_mall_products.id}. Enables catalog linkage and context.
  product_id String? @db.Uuid

  /// Order's {@link ai_mall_orders.id} if relevant to purchase. Enables context escalation for support.
  order_id String? @db.Uuid

  /// Inquiry summary/title. Requirements: concise topic for display/listing. Example: 'Shipping delay inquiry'.
  title String

  /// Inquiry full content. Structurally distinct from comments. Example: 'When will this ship?'
  body String

  /// Current process state (e.g., 'open','answered','closed','deleted'). Tracks and enables workflow filtering.
  status String

  /// When the inquiry was created. Enables audit/chronology.
  created_at DateTime @db.Timestamptz

  /// Last update. Enables audit, change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  inquiry_customer ai_mall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  inquiry_product  ai_mall_products? @relation(fields: [product_id], references: [id], onDelete: Cascade)
  inquiry_order    ai_mall_orders?   @relation(fields: [order_id], references: [id], onDelete: Cascade)

  ai_mall_inquiry_comments ai_mall_inquiry_comments[]

  @@unique([customer_id, created_at])
  @@index([product_id, created_at])
  @@index([order_id])
  @@index([status])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Inquiry Comment] Implements communication/follow-up on inquiries per requirements (threaded support, role separation). Maintains 3NF, separate from ai_mall_inquiries. Supports moderation, threading via parent_id (self-reference), and role-based authorship.
///
