schemas.schema-10-articles.prisma:
/// Article entity - This implements the platform article/post requirement for news, blog content, or editorial material. Articles serve as informational or promotional content authored by admins (or sellers, if permitted). Each article can have multiple comments and be assigned to one or more article categories. Fully normalized by separating main article data, comments, and category mappings. For example, an admin can publish new feature updates, or a seller can post promotional articles. Key relationships: references to authors (admin or seller), links to category and comments. Special behaviors: articles can be edited or unpublished but retain audit trail via snapshots if needed.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_articles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each article.
  id String @id @db.Uuid

  /// Reference to admin author's {@link ai_mall_admins.id}. Indicates article is authored by an admin. Nullable if authored by seller.
  author_admin_id String? @db.Uuid

  /// Reference to seller author's {@link ai_mall_sellers.id}. Indicates article is authored by a seller. Nullable if authored by admin.
  author_seller_id String? @db.Uuid

  /// Assigned article category's {@link ai_mall_article_categories.id}. Categorizes article for navigation, filtering, or display/grouping.
  category_id String @db.Uuid

  /// Title of the article - Implements the requirement for article headline. Main descriptor for search, display, and navigation. Fully atomic and required.
  title String

  /// SEO-friendly slug/URL segment for the article. Used for human-readable and indexable links. Example: 'ai-mall-launch-event'. Ensures normalization by separating from title/body.
  slug String

  /// Main content body - Implements article textual/HTML content as fully normalized field. No derived or summary fields included. For example, product launch details, guides, etc.
  body String

  /// Publication flag - Indicates whether article is publicly visible or in draft/unpublished state. Implements content moderation flow. Not calculated; atomic status only.
  published Boolean

  /// Pinned flag for featured or promoted articles. Atomic flag (true if highlighted), maintains fully normalized structure.
  pinned Boolean

  /// Creation timestamp for the article. Atomic event time, not derived. Enforces audit trail requirements.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the article. Used for audit and change tracking per non-functional requirements. Not calculated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_articles_admin    ai_mall_admins?            @relation(fields: [author_admin_id], references: [id], onDelete: Cascade)
  fk_articles_seller   ai_mall_sellers?           @relation(fields: [author_seller_id], references: [id], onDelete: Cascade)
  fk_articles_category ai_mall_article_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  ai_mall_article_comments ai_mall_article_comments[]

  @@unique([slug])
  @@index([author_admin_id])
  @@index([author_seller_id])
  @@index([category_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Article comment entity - Implements the ability for users to comment on articles as per interaction and personalization requirements. Allows multiple comments per article, supports threaded/hierarchical replies via parent_id. Maintains 3NF by separating comment text, article association, and user identity. Usage example: customers, sellers, or admins can add discussion/comments on news, guides, etc. Key relationships: links to article, parent (for threads), and comment author (customer, seller, or admin). Special behaviors: moderation, visibility, and deletion handled at application layer.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_article_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment.
  id String @id @db.Uuid

  /// Reference to parent article's {@link ai_mall_articles.id}. Each comment belongs to one article.
  article_id String @db.Uuid

  /// Reference to commenting customer's {@link ai_mall_customers.id}, if comment was left by a customer. Nullable if comment by seller/admin.
  author_customer_id String? @db.Uuid

  /// Reference to commenting seller's {@link ai_mall_sellers.id}, if comment was left by a seller. Nullable if comment by customer/admin.
  author_seller_id String? @db.Uuid

  /// Reference to commenting admin's {@link ai_mall_admins.id}, if comment was left by an admin. Nullable if comment by customer/seller.
  author_admin_id String? @db.Uuid

  /// Optional self-reference to parent comment ({@link ai_mall_article_comments.id}) for threaded discussions. Null for top-level comments, set for replies.
  parent_id String? @db.Uuid

  /// Main comment text body - Implements atomic requirement to store actual user comment content. Fully normalized; no derived sentiment or summary fields. For example: customer leaves question, seller provides answer.
  body String

  /// Creation timestamp - Meets audit/auditability requirement for comment event. Not calculated.
  created_at DateTime @db.Timestamptz

  /// Last edit timestamp for the comment. Supports moderation and edit trail functionality per requirements.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_article_comments_article ai_mall_articles          @relation(fields: [article_id], references: [id], onDelete: Cascade)
  fk_comments_customer        ai_mall_customers?        @relation(fields: [author_customer_id], references: [id], onDelete: Cascade)
  fk_comments_seller          ai_mall_sellers?          @relation(fields: [author_seller_id], references: [id], onDelete: Cascade)
  fk_comments_admin           ai_mall_admins?           @relation(fields: [author_admin_id], references: [id], onDelete: Cascade)
  fk_comments_parent          ai_mall_article_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_mall_article_comments[] @relation("recursive")

  @@index([author_customer_id])
  @@index([author_seller_id])
  @@index([author_admin_id])
  @@index([parent_id])
  @@index([article_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Article category entity - Implements requirement for grouping articles for organization, navigation, filtering, and SEO. Maintains 3NF by separating categorical metadata from articles. For example, guides, news, policy updates, etc. Each category can be assigned to multiple articles. Hierarchy (parent-child) allows nesting categories. Special behaviors: if parent_id is set, forms category tree; else is a root-level category. Application can enforce business logic on parent/child constraints.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_article_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each article category.
  id String @id @db.Uuid

  /// Optional parent category's {@link ai_mall_article_categories.id} for category hierarchy and nesting. Null for root categories.
  parent_id String? @db.Uuid

  /// Category name - Implements the requirement for unique, human-readable article category label. Ensures normalization.
  name String

  /// SEO-friendly category slug for URLs/navigation. Must be unique within categories. Example: 'news-updates'. Maintains normalization by not duplicating category name.
  slug String

  /// Optional category description - Implements meta/SEO or UI tooltip requirement. Nullable, not required.
  description String?

  //----
  // RELATIONS
  //----
  fk_article_categories_parent ai_mall_article_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  ai_mall_articles ai_mall_articles[]
  recursive        ai_mall_article_categories[] @relation("recursive")

  @@unique([slug])
  @@index([parent_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-11-analytics.prisma:
/// Analytics Event Entity - This implements the requirements for tracking distinct analytics events as demanded in the advanced analytics and AI documentation. 
///
/// Business explanation: Each row represents a single captured analytics event (click, page view, purchase, search, error) generated by any user or system process. Maintains 3NF compliance—event details and context are atomic and not derived. For example, when a customer adds an item to their cart, a new analytics event is created referencing its type and holding contextual payload (serialized JSON). 
///
/// Key relationships: Ties to ai_mall_analytics_event_types for type definition, can reference actor tables (not directly modeled here). 
/// Special behaviors: Loosely coupled with user/session IDs for flexibility; all business logic for attribution is handled externally.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_analytics_events {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each analytics event record.
  id String @id @db.Uuid

  /// Event type reference - Links to event type definition in {@link ai_mall_analytics_event_types.id} to ensure event categorization adheres to system-defined taxonomy. Relationship is required for classification.
  event_type_id String @db.Uuid

  /// Event Occurrence Timestamp - Implements the requirement to record the exact UTC time of the event occurrence. Maintains strict normalization with explicit, unambiguous timestamps. For example, used for all time-based analytics, daily active users, or sequence analysis.
  occurred_at DateTime @db.Timestamptz

  /// Actor Reference (Loose/Flexible) - Optionally associates an event with any system actor (customer, seller, admin). Implements the requirement for user attribution analytics (inferred by external joins). Maintains normalization by not duplicating user state; can be null for system/bot events.
  actor_id String? @db.Uuid

  /// Session Reference (Loose/Flexible) - Optionally attributes the event to a browsing session or device identity for anonymous event tracking. Enforces normalization by keeping only the session UUID here; session metadata is external.
  session_id String? @db.Uuid

